Imagine que o carregamento da fonte Inter falha. O que o usuário vê com este `App.js`?

```jsx
SplashScreen.preventAutoHideAsync();

export default function App() {
  const [fontesCarregadas, erroFonte] = useFonts({ Inter_400Regular, Inter_700Bold });

  useEffect(() => {
    if (fontesCarregadas) SplashScreen.hideAsync();
  }, [fontesCarregadas]);

  if (!fontesCarregadas) return null;
  // return com TemaProvider e Inicio
}
```
